#include <Arduino.h>
#include <IRremoteESP8266.h>
#include <IRsend.h>

namespace {
constexpr uint16_t kIrLedPin = 4; // Target GPIO configured for IR LED
}

// Initialize IRsend with hardware RMT enabled
// pin: GPIO output pin
// inverted: false (standard active-high drive for NPN/MOSFET)
// use_modulation: true (38kHz carrier generated by RMT hardware)
static IRsend irsend(kIrLedPin, false, true);

void setupIrTx() {
    irsend.begin();
}

void sendIrCommand(uint8_t opcode, uint64_t data, uint16_t nbits) {
  switch (opcode) {
    case 0x02: // OPCODE_IR_NEC
      irsend.sendNEC(data, nbits);
      break;
    case 0x03: // OPCODE_IR_SONY
      irsend.sendSony(data, nbits);
      break;
    case 0x04: // OPCODE_IR_RC5
      irsend.sendRC5(data, nbits);
      break;
    default:
      Serial.printf("Unknown IR opcode: 0x%02X\n", opcode);
      break;
  }
}
